/* Canada regional shore: GSHHS intermediate Basemap polygons, 196 x 112.
   Values encode 25 hex-footprint samples: <20% land sea (0), 20–80% coast (1),
   >80% inland land (2). Interior GSHHS lakes are water; mixed hexes retain
   land access without fabricating wide navigable inland sea lanes.
   RLE bytes: top two bits class, lower six bits length-1. */
(function(root) {
  'use strict';
  const DATA = '';
  const bytes = typeof atob === 'function' ? atob(DATA) : Buffer.from(DATA,'base64').toString('latin1');
  const coverage = new Uint8Array(196*112);
  let i=0;
  for(let j=0;j<bytes.length;j++){
    const b=bytes.charCodeAt(j),kind=b>>6,repeat=1+(b&63);
    if(kind>2||i+repeat>coverage.length) throw Error('Canada coastline data corrupt');
    coverage.fill(kind,i,i+repeat);i+=repeat;
  }
  if(i!==coverage.length) throw Error('Canada coastline data incomplete: '+i);
  const api={cols:196,rows:112,west:-147,east:-40,north:83.8,south:41,coverage};
  root.CANADA_GEOGRAPHY=api;
  if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
